sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var logger = new bfd_CommsLogger();
    var caseId = current.getUniqueValue();

    // 1) bfd_notify_info_required — case_status -> pending_customer_information
    if (current.case_status.changesTo('pending_customer_information')) {
        logger.logOutbound(
            caseId,
            'email',
            'Action needed on your case',
            'We asked you for additional information: the date and amount of the disputed activity, whether the card is still in your possession, and any supporting evidence. Full card numbers, PINs and passcodes are never requested.',
            'bfd_case_comms_log_br:info_required'
        );
    }

    // 2) bfd_notify_card_action — card_action -> block / replacement
    if (
        current.card_action.changesTo('temporary_block') ||
        current.card_action.changesTo('permanent_block') ||
        current.card_action.changesTo('replacement_issued')
    ) {
        logger.logOutbound(
            caseId,
            'email',
            'Security action on your card',
            'We notified you that the action "' +
                current.card_action.getDisplayValue() +
                '" has been applied to the card on this case. Only the masked card reference was included in the message.',
            'bfd_case_comms_log_br:card_action'
        );
    }

    // 3) bfd_notify_provisional_credit — provisional_credit_flag -> true
    if (current.provisional_credit_flag.changesTo(true)) {
        logger.logOutbound(
            caseId,
            'email',
            'Provisional credit applied',
            'We told you that a provisional credit of ' +
                current.getValue('provisional_credit_amount') +
                ' ' +
                current.getValue('currency') +
                ' has been applied to your account while the investigation continues.',
            'bfd_case_comms_log_br:provisional_credit'
        );
    }
})(current, previous);
